TLM.f("Sancti/06-11",{"officium":"S. Barnabæ Apostoli","rule":["ex C1;","Gloria","Credo","Prefatio=Apostolis"],"ruleInherited":["Psalmi Dominica","Antiphonas horas","Psalm5 Vespera=116","Psalm5 Vespera3=138"],"fallback":"Commune/C1","sections":{"Introitus":[{"k":"ref","la":"Ps 138:17"},{"k":"text","la":"Mihi autem nimis honoráti sunt amíci tui, Deus: nimis confortátus est principátus eórum."},{"k":"ref","la":"Ps 138:1-2"},{"k":"text","la":"Dómine, probásti me et cognovísti me: tu cognovísti sessiónem meam et resurrectiónem meam."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Mihi autem nimis honoráti sunt amíci tui, Deus: nimis confortátus est principátus eórum."}],"Oratio":[{"k":"text","la":"Deus, qui nos beáti Bárnabæ Apóstoli tui méritis et intercessióne lætíficas: concéde propítius; ut, qui tua per eum benefícia póscimus, dono tuæ grátiæ consequámur."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Actuum Apostolórum"},{"k":"ref","la":"Act 11:21-26; 13:1-3"},{"k":"text","la":"In diébus illis: Multus númerus credéntium Antiochíæ convérsus est ad Dóminum. Pervénit autem sermo ad aures ecclésiæ, quæ erat Jerosólymis, super istis: et misérunt Bárnabam usque ad Antiochíam. Qui cum pervenísset et vidísset grátiam Dei, gavísus est: et hortabátur omnes in propósito cordis permanére in Dómino: quia erat vir bonus, et plenus Spiritu Sancto et fide. Et appósita est multa turba Dómino. Proféctus est autem Bárnabas Tarsum, ut quæreret Saulum: quem cum invenísset, perdúxit Antiochíam. Et annum totum conversáti sunt ibi in ecclésia: et docuérunt turbam multam, ita ut cognominaréntur primum Antiochíæ discípuli Christiáni. Erant autem in ecclésia, quæ erat Antiochíæ, prophétæ et doctóres, in quibus Bárnabas, et Simon qui vocabátur Niger, et Lúcius Cyrenénsis, et Mánahen qui erat Heródis Tetrárchæ collactáneus, et Saulus. Ministrántibus autem illis Dómino et jejunántibus, dixit illis Spíritus Sanctus: Segregáte mihi Saulum et Bárnabam in opus, ad quod assúmpsi eos. Tunc jejunántes et orantes imponentésque eis manus, dimisérunt illos."}],"Graduale":[{"k":"ref","la":"Ps 18:5; 18:2"},{"k":"text","la":"In omnem terram exívit sonus eórum: et in fines orbis terræ verba eórum."},{"k":"text","la":"Cœli enárrant glóriam Dei: et ópera mánuum ejus annúntiat firmaméntum. Allelúja, allelúja.","mark":"V"},{"k":"ref","la":"Ps 15:16"},{"k":"text","la":"Ego vos elégi de mundo, ut eátis et fructum afferátis: et fructus vester maneat. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 10:16-22"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Ecce, ego mitto vos sicut oves in médio lupórum. Estóte ergo prudéntes sicut serpentes, et símplices sicut colúmbæ. Cavéte autem ab homínibus. Tradent enim vos in concíliis, et in synagógis suis flagellábunt vos: et ad præsides et ad reges ducémini propter me in testimónium illis et géntibus. Cum autem tradent vos, nolíte cogitáre, quómodo aut quid loquámini: dábitur enim vobis in illa hora, quid loquámini. Non enim vos estis, qui loquímini, sed Spíritus Patris vestri, qui lóquitur in vobis. Tradet autem frater fratrem in mortem, et pater fílium: et insúrgent fílii in paréntes, et morte eos affícient: et éritis odio ómnibus propter nomen meum: qui autem perseveráverit usque in finem, hic salvus erit."}],"Offertorium":[{"k":"ref","la":"Ps 44:17-18"},{"k":"text","la":"Constítues eos príncipes super omnem terram: mémores erunt nóminis tui, Dómine, in omni progénie et generatióne."}],"Secreta":[{"k":"text","la":"Múnera, Dómine, obláta sanctífica, et, intercedénte beáto Bárnaba Apostolo tuo, nos per hæc a peccatórum nostrórum máculis emúnda."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Matt 19:28"},{"k":"text","la":"Vos, qui secúti estis me, sedébitis super sedes, judicántes duódecim tribus Israël."}],"Postcommunio":[{"k":"text","la":"Súpplices te rogámus, omnípotens Deus: ut, quos tuis réficis sacraméntis, intercedénte beáto Bárnaba Apóstolo tuo, tibi étiam plácitis móribus dignánter tríbuas deservíre."},{"k":"macro","name":"Per Dominum"}]},"hr":{"4ce2969ae90d1d66":{"t":"Ps 138, 17, Ps 138, 1-2\n(Ps 138, 17) Nadasve častim tvoje prijatelje, Bože, jer je velika uloga vlasti njihove. (Ps 138, 1-2) Gospodine, ti si me kušao i spoznao, tebi je poznat moj počinak i moje uskrsnuće.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 138, 17) Nadasve častim tvoje prijatelje, Bože, jer je velika uloga vlasti njihove."},"a6d65d3d89be8969":{"t":"<i>Pomolimo se</i>.\nBože, koji nas razveseljuješ zaslugama i zagovorom blaženog Barnabe apostola svoga, daj milostiv da kao dar tvoje milosti postignemo tvoja dobročinstva koja po njemu molimo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"5f2392c743a5b781":{"t":"Dj 11, 21-26, 13, 1-3\nČitanje Djela apostolskih. U one dane mnogi u Antiohiji povjeruju i obrate se Gospodinu. Dočuje to skup u Jeruzalemu i pošalju u Antiohiju Barnabu, Dođe onamo, vidi Božju milost, razveseli se potičući sve da odlučno ustraju u Gospodinu. Bio je dobar čovjek, pun Duha Svetoga i vjere, i mnogo naroda pristane uz Gospodina. Odonud krene Barnaba u Tarz da potraži Savla. Nađe ga, dovede ga u Antiohiju i čitavu su godinu boravili u onoj crkvenoj zajednici i poučavali brojni narod. Učenici u Antiohiji prvi su se prozvali kršćanima. U antiohijskoj je crkvi bilo proroka i učitelja, među kojima Barnaba, Šimun Niger, Lucije Cirenac, Manahen, koji se odgajao zajedno s tetrarhom Herodom, i Savao. Za vrijeme Gospodnje službe i posta, objavi im Duh Sveti: Odvojite mi Barnabu i Savla za djelo za koje sam ih i pozvao. Tada su postili i molili, i kada su na njih položili ruke, otpuste ih."},"ddb4aa05ce27dfc8":{"t":"Ps 18, 5 et 2\nPo svoj zemlji iziđe njihov glas, i do na kraj svijeta njihova nauka. Nebesa pripovijedaju slavu Božju i svod nebeski naviješta djelo njegovih ruku.\n\nIo 15, 16\n<i>Aleluja</i>, <i>aleluja</i>.\nJa sam vas izabrao od svijeta da idete i plod donesete i plod vaš da ostane. <i>Aleluja</i>."},"b7c6408ffcda5d52":{"t":"Mt 10, 16-22\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme reče Isus svojim učenicima: Evo, ja vas šaljem kao ovce među vukove. Zato budite mudri kao zmije, a bezazleni kao golubovi. Čuvajte se ljudi, jer će vas predavati sudovima, bičevat će vas po svojim zbornicama, radi mene vodit će vas pred upravitelje i vladare, da svjedočite njima i nevjernicima. Kada budete u njihovim rukama, ne mučite se smišljajući kako ili što ćete govoriti, jer će vam se onoga časa objaviti što ćete govoriti. Nećete govoriti vi, nego će Duh vašega Oca govoriti iz vas. Predavat će na smrt brat brata, otac sina, dizat će se djeca na roditelje tražeći njihovu smrt. Svi će vas mrziti radi mene, ali tko ustraje do kraja, spasit će se."},"93805934ca9284fe":{"t":"Ps 44, 17-18\nPostavit ćeš ih za knezove nad svom zemljom. Spominjat će tvoje ime, Gospodine, u svakom pokoljenju i naraštaju."},"bbfa985cf2ee5526":{"t":"Posveti, Gospodine, prikazane darove i po zagovoru blaženog Barnabe apostola svoga očisti nas od ljaga naših grijeha.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"fdbfd5e8960de5c2":{"t":"Uistinu je dostojno, i pravedno, pravo i spasonosno tebe, Gospodine, vječni Pastiru, smjerno moliti da stado svoje ne ostaviš, nego da ga po svojim blaženim apostolima neprestano štitiš i čuvaš, da njime ravnaju isti poglavari, koje si mu postavio na čelo kao pastire i namjesnike svoga djela. – I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:"},"4379ab930a0e53cb":{"t":"Mt 19, 28\nVi koji ste pošli za mnom sjedit ćete na prijestoljima i suditi dvanaest plemena Izraelovih."},"f44ef2462970581d":{"t":"<i>Pomolimo se</i>.\nPonizno te molimo, svemogući Bože, daj da ti oni koje krijepiš svojim otajstvima po zagovoru blaženoga Barnabe tvoga apostola dostojno služe ugodnim životom.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
